include('../assets/head.php');
require_once __DIR__ . '/lib/page.php';
$con = sat_db();
sat_page_inicio('contabilidad', 'Reglas contables');
$id=(int)($_GET['id_empresa']??0);if($id<=0)die('Selecciona una empresa');AccountingService::bootstrapEmpresa($con,$id);$cts=mysqli_query($con,"SELECT * FROM sat_cuentas_contables WHERE id_empresa=$id AND activo=1 AND permite_movimientos=1 ORDER BY numero_cuenta");$regs=mysqli_query($con,"SELECT r.*,c.numero_cuenta,c.nombre cuenta FROM sat_reglas_contables r JOIN sat_cuentas_contables c ON c.id_cuenta=r.id_cuenta WHERE r.id_empresa=$id ORDER BY r.prioridad DESC,r.id_regla DESC");?>
<h3>Reglas de clasificación y aprendizaje</h3><p class="text-muted">Cuando un concepto coincida con una regla, se asignará automáticamente a la cuenta indicada. La descripción puede ser una palabra o frase contenida en el concepto.</p>
<div class="sat-card p-4 mb-4"><form class="row g-3" method="post" action="php/postGuardarRegla.php"><input type="hidden" name="id_empresa" value="<?=$id?>"><div class="col-md-3"><label class="form-label">Nombre regla</label><input class="form-control" name="nombre" required></div><div class="col-md-2"><label class="form-label">Tipo</label><select class="form-control" name="tipo_relacion"><option>AMBAS</option><option>RECIBIDA</option><option>EMITIDA</option></select></div><div class="col-md-2"><label class="form-label">RFC tercero</label><input class="form-control" name="rfc_tercero"></div><div class="col-md-2"><label class="form-label">Clave ProdServ</label><input class="form-control" name="clave_prod_serv"></div><div class="col-md-3"><label class="form-label">Texto en descripción</label><input class="form-control" name="patron_descripcion" placeholder="ej. gasolina"></div><div class="col-md-5"><label class="form-label">Cuenta</label><select class="form-control" name="id_cuenta" required><?php while($c=mysqli_fetch_assoc($cts)):?><option value="<?=$c['id_cuenta']?>"><?=e($c['numero_cuenta'].' - '.$c['nombre'])?></option><?php endwhile?></select></div><div class="col-md-2"><label class="form-label">Movimiento</label><select class="form-control" name="lado"><option>AUTO</option><option>CARGO</option><option>ABONO</option></select></div><div class="col-md-2"><label class="form-label">Prioridad</label><input type="number" class="form-control" name="prioridad" value="100"></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-primary">Guardar y aprender</button></div></form></div>
<div class="sat-card p-4"><table class="sat-tabla"><thead><tr><th>Regla</th><th>Aplica a</th><th>Condiciones</th><th>Cuenta</th><th>Lado</th><th>Usos</th><th>Confianza</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($regs)):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['tipo_relacion'])?></td><td><small>RFC: <?=e($r['rfc_tercero']?:'*')?><br>Clave: <?=e($r['clave_prod_serv']?:'*')?><br>Texto: <?=e($r['patron_descripcion']?:'*')?></small></td><td><?=e($r['numero_cuenta'].' - '.$r['cuenta'])?></td><td><?=e($r['lado'])?></td><td><?=e($r['usos'])?></td><td><?=number_format($r['confianza']*100,0)?>%</td></tr><?php endwhile?></tbody></table></div><?php sat_page_fin(); include('../assets/footer.php');?>
